<?php declare(strict_types=1); require_once __DIR__.'/lib/auth.php'; if(current_user()){header('Location: workspace.php');exit;} $error='';$notice=isset($_GET['registered'])?'Đăng ký thành công. Hãy kiểm tra Email và bấm Link kích hoạt.':(isset($_GET['expired'])?'Tài khoản đã hết hạn, chưa kích hoạt hoặc bị khóa.':''); if($_SERVER['REQUEST_METHOD']==='POST'){ $email=strtolower(trim((string)($_POST['email']??'')));$pass=(string)($_POST['password']??'');try{$q=db()->prepare('SELECT id,name,email,password_hash,status,role,expires_at,email_verified_at FROM users WHERE email=? LIMIT 1');$q->execute([$email]);$u=$q->fetch();if(!$u||!password_verify($pass,$u['password_hash']))$error='Email hoặc mật khẩu không đúng.';elseif(empty($u['email_verified_at']))$error='Tài khoản chưa được kích hoạt. Hãy kiểm tra Email.';elseif(!user_is_active($u))$error='Tài khoản đã hết hạn hoặc bị khóa.';else{db()->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([$u['id']]);login_user($u);header('Location: workspace.php');exit;}}catch(Throwable $e){$error='Không thể đăng nhập. Kiểm tra cấu hình MySQL.';}} ?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Đăng nhập - VideoDubing AI</title><link rel="stylesheet" href="assets/css/app.css"></head><body><main class="auth-page"><section class="auth-card"><a class="auth-brand" href="index.php">▶ <strong>VideoDubing AI</strong></a><h1>Đăng nhập</h1><p class="hint">Đăng nhập để sử dụng VideoDubing AI.</p><?php if($notice):?><div class="alert ok"><?=htmlspecialchars($notice)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><div class="field"><label>Email</label><input class="input" type="email" name="email" required autofocus></div><div class="field"><label>Mật khẩu</label><input class="input" type="password" name="password" required></div><button class="primary" style="width:100%">ĐĂNG NHẬP</button></form><p class="auth-bottom"><a href="forgot-password.php">Quên mật khẩu?</a></p><p class="auth-bottom">Chưa có tài khoản? <a href="register.php">Đăng ký</a></p></section></main></body></html>